def group_anagrams(strs: list) -> list:
    from collections import defaultdict
    groups = defaultdict(list)
    for s in strs:
        key = ''.join(sorted(s))
        groups[key].append(s)
    result = [sorted(g) for g in groups.values()]
    return sorted(result, key=lambda x: (len(x), x[0] if x else ''))
